document.addEventListener('DOMContentLoaded',()=>{const card=document.querySelector('.card');if(!card)return;const modal=document.createElement('div');modal.className='place-modal';modal.innerHTML='<div class="place-panel"><button class="place-close" aria-label="Fechar">×</button><div class="place-image"></div><span class="eyebrow">DETALHES DO DESTINO</span><h2 id="place-name">Praia do Aventureiro</h2><p id="place-copy">Areia clara, mar aberto e aquele visual que faz você esquecer a hora.</p><div class="place-info"><span><b>Local</b><br>Ilha Grande, Angra dos Reis</span><span><b>Acesso</b><br>Barco + trilha curta</span><span><b>Duração</b><br>Meio período</span><span><b>Faixa de valor</b><br>R$ 80–180</span></div><button class="place-save">Salvar no roteiro</button></div>';document.body.appendChild(modal);card.addEventListener('click',e=>{if(e.target.closest('button'))return;modal.classList.add('show')});modal.addEventListener('click',e=>{if(e.target===modal||e.target.closest('.place-close'))modal.classList.remove('show');if(e.target.closest('.place-save')){document.querySelectorAll('.actions button')[1].click();modal.classList.remove('show')}});const css=document.createElement('style');css.textContent='.place-modal{display:none;position:fixed;inset:0;background:rgba(20,43,58,.72);z-index:10;padding:20px;place-items:center}.place-modal.show{display:grid}.place-panel{background:#f7f4ec;border-radius:24px;padding:18px;max-width:470px;width:100%;position:relative;box-shadow:0 20px 70px rgba(0,0,0,.25)}.place-close{position:absolute;right:14px;top:12px;width:36px;height:36px;border:0;border-radius:50%;background:white;font-size:25px;cursor:pointer}.place-image{height:180px;border-radius:16px;margin-bottom:18px;background:linear-gradient(145deg,#f2b276,#2a7680 55%,#123b4d)}.place-panel h2{font-size:34px;letter-spacing:-.05em;margin:7px 0}.place-panel p{color:#66808b;line-height:1.5}.place-info{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin:18px 0}.place-info span{background:white;border-radius:12px;padding:11px;font-size:13px;line-height:1.45}.place-save{width:100%;border:0;border-radius:12px;padding:13px;background:#f26b4f;color:white;font-weight:700;cursor:pointer}';document.head.appendChild(css)});
